"""Behavioral checks for stream_rows and take.

Run from the project root: ``python3 checks/behavior_checks.py``
"""
import gc
import os
import sys

sys.path.insert(0, os.getcwd())

from src.consumer import take
from src.resource import Rows
from src.service import stream_rows


class CleanupError(Exception):
    pass


class ReadError(Exception):
    pass


class TransformError(Exception):
    pass


class FailingRows:
    """A row resource that can fail on a specific read and/or when closed."""

    def __init__(self, rows, fail_read_at=None, fail_close=False):
        self.rows = list(rows)
        self.index = 0
        self.reads = 0
        self.closes = 0
        self.fail_read_at = fail_read_at
        self.fail_close = fail_close

    def read_next(self):
        self.reads += 1
        if self.fail_read_at is not None and self.reads == self.fail_read_at:
            raise ReadError("read failed")
        if self.index == len(self.rows):
            return None
        value = self.rows[self.index]
        self.index += 1
        return value

    def close(self):
        self.closes += 1
        if self.fail_close:
            raise CleanupError("close failed")


# --- stream_rows -----------------------------------------------------------

def test_lazy_and_unstarted_close():
    resource = FailingRows([1, 2, 3])
    stream = stream_rows(resource, lambda value: value * 2)
    assert (resource.reads, resource.closes) == (0, 0)
    stream.close()
    assert (resource.reads, resource.closes) == (0, 0)
    assert list(stream) == []
    assert (resource.reads, resource.closes) == (0, 0)


def test_order_values_and_exhaustion():
    resource = Rows([1, 2, 3])
    assert list(stream_rows(resource, lambda value: value * 2)) == [2, 4, 6]
    assert (resource.reads, resource.closes) == (4, 1)


def test_lazy_one_row_at_a_time():
    resource = Rows([1, 2, 3])
    stream = stream_rows(resource, lambda value: value + 10)
    assert (resource.reads, resource.closes) == (0, 0)
    assert next(stream) == 11 and (resource.reads, resource.closes) == (1, 0)
    assert next(stream) == 12 and (resource.reads, resource.closes) == (2, 0)
    stream.close()
    assert (resource.reads, resource.closes) == (2, 1)
    assert stream.close() is None
    assert resource.closes == 1
    try:
        next(stream)
    except StopIteration:
        pass
    else:
        raise AssertionError("closed stream should be exhausted")


def test_explicit_close_closes_once():
    resource = Rows([1, 2, 3])
    stream = stream_rows(resource, lambda value: value)
    next(stream)
    stream.close()
    stream.close()
    assert resource.closes == 1


def test_read_error_closes_and_propagates():
    resource = FailingRows([1, 2, 3], fail_read_at=3)
    try:
        list(stream_rows(resource, lambda value: value * 2))
    except ReadError:
        pass
    else:
        raise AssertionError("read error should propagate")
    assert (resource.reads, resource.closes) == (3, 1)


def test_transform_error_stops_reading():
    resource = Rows([1, 2, 3])
    seen = []

    def transform(value):
        seen.append(value)
        if value == 2:
            raise TransformError("bad transform")
        return value * 10

    try:
        list(stream_rows(resource, transform))
    except TransformError:
        pass
    else:
        raise AssertionError("transform error should propagate")
    assert seen == [1, 2]
    assert (resource.reads, resource.closes) == (2, 1)


def test_read_error_wins_over_cleanup_error():
    resource = FailingRows([1, 2, 3], fail_read_at=2, fail_close=True)
    try:
        list(stream_rows(resource, lambda value: value))
    except ReadError:
        pass
    except CleanupError:
        raise AssertionError("cleanup error replaced the read error")
    else:
        raise AssertionError("expected an error")
    assert resource.closes == 1


def test_transform_error_wins_over_cleanup_error():
    resource = FailingRows([1, 2], fail_close=True)
    try:
        list(stream_rows(resource, lambda value: 1 / 0))
    except ZeroDivisionError:
        pass
    except CleanupError:
        raise AssertionError("cleanup error replaced the transform error")
    else:
        raise AssertionError("expected an error")
    assert resource.closes == 1


def test_cleanup_error_propagates_on_exhaustion():
    resource = FailingRows([1], fail_close=True)
    try:
        list(stream_rows(resource, lambda value: value))
    except CleanupError:
        pass
    else:
        raise AssertionError("cleanup error should propagate")
    assert resource.closes == 1


def test_cleanup_error_propagates_on_explicit_close():
    resource = FailingRows([1, 2], fail_close=True)
    stream = stream_rows(resource, lambda value: value)
    assert next(stream) == 1
    try:
        stream.close()
    except CleanupError:
        pass
    else:
        raise AssertionError("cleanup error should propagate")
    assert resource.closes == 1
    try:
        next(stream)
    except StopIteration:
        pass
    else:
        raise AssertionError("iterator should be closed")
    stream.close()
    assert resource.closes == 1


def test_abandoned_generator_closes_resource():
    resource = Rows([1, 2, 3])
    stream = stream_rows(resource, lambda value: value)
    assert next(stream) == 1
    del stream
    gc.collect()
    assert (resource.reads, resource.closes) == (1, 1)


# --- take ------------------------------------------------------------------

def test_take_zero_does_not_start_stream():
    resource = Rows([1, 2, 3])
    assert take(resource, lambda value: value * 2, 0) == []
    assert (resource.reads, resource.closes) == (0, 0)


def test_take_negative_does_not_start_stream():
    resource = Rows([1, 2, 3])
    assert take(resource, lambda value: value * 2, -5) == []
    assert (resource.reads, resource.closes) == (0, 0)


def test_take_partial_closes_iterator():
    resource = Rows([1, 2, 3, 4])
    assert take(resource, lambda value: value * 2, 2) == [2, 4]
    assert (resource.reads, resource.closes) == (2, 1)


def test_take_exact_limit_does_not_read_eof():
    resource = Rows([1, 2, 3])
    assert take(resource, lambda value: value, 3) == [1, 2, 3]
    assert (resource.reads, resource.closes) == (3, 1)


def test_take_past_end():
    resource = Rows([1, 2])
    assert take(resource, lambda value: value + 1, 10) == [2, 3]
    assert (resource.reads, resource.closes) == (3, 1)


def test_take_read_error_closes_and_propagates():
    resource = FailingRows([1, 2, 3], fail_read_at=2)
    try:
        take(resource, lambda value: value, 10)
    except ReadError:
        pass
    else:
        raise AssertionError("read error should propagate")
    assert resource.closes == 1


def test_take_transform_error_closes_and_propagates():
    resource = Rows([1, 2, 3])

    def transform(value):
        if value == 2:
            raise TransformError("bad")
        return value

    try:
        take(resource, transform, 10)
    except TransformError:
        pass
    else:
        raise AssertionError("transform error should propagate")
    assert (resource.reads, resource.closes) == (2, 1)


def test_take_transform_error_wins_over_cleanup_error():
    resource = FailingRows([1, 2], fail_close=True)

    def transform(value):
        raise TransformError("bad")

    try:
        take(resource, transform, 5)
    except TransformError:
        pass
    except CleanupError:
        raise AssertionError("cleanup error replaced the transform error")
    else:
        raise AssertionError("expected an error")
    assert resource.closes == 1


def test_take_cleanup_error_propagates_when_limit_reached():
    resource = FailingRows([1, 2], fail_close=True)
    try:
        take(resource, lambda value: value, 1)
    except CleanupError:
        pass
    else:
        raise AssertionError("cleanup error should propagate")
    assert resource.closes == 1


def main():
    tests = [
        (name, value)
        for name, value in sorted(globals().items())
        if name.startswith("test_") and callable(value)
    ]
    for name, test in tests:
        test()
        print("ok -", name)
    print("%d checks passed" % len(tests))


if __name__ == "__main__":
    main()
